import{_,o as a,c as t,ae as o}from"./chunks/framework.Iv6F95cJ.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/algo-beauty/课程迭代-全新交付71讲音频.md","filePath":"books/algo-beauty/课程迭代-全新交付71讲音频.md"}'),p={name:"books/algo-beauty/课程迭代-全新交付71讲音频.md"};function n(r,e,s,l,i,c){return a(),t("div",null,[...e[0]||(e[0]=[o("<p>你好，我是极客时间专栏主编李佳。今天是2021年1月8日，距离《数据结构与算法之美》课程结课快2年的时间，我代表极客时间教研团队，在此向你汇报一下这门课程的情况和迭代规划。</p><p>2020年12月7日，咱们这门课程的订阅超过了十万，这也就意味着我们成为了极客时间上最大的一个班集体。十万多位同学一起死磕数据结构和算法，这件事想想都振奋人心。</p><p>在我们的课程里，我们的文章有45,443次收藏，有438,273处划线，36,684条笔记，22,076条留言。这些学习数据都是我们这个班集体一起学习、一起进步的见证。</p><p>特别地，在课程留言里，你不仅分享了自己的学习收获、心得与经验，提出了自己的疑惑和问题，还指出了音频里的错误之处，真心感谢你的每一次批评指正。正是基于大家的反馈，我们决定重新交付课程音频，修改之前音频里的错误内容，同时，也在音频迭代的过程中，重新检查一遍文稿内容。这样，后面新加入的同学可以获得更好的学习体验，已经学完的同学也可以在复习的时候有不一样的感受。</p><p>这次音频迭代涉及课程里的71讲内容，我们会分2次全部替换完。音频替换计划如下：</p><ul><li>1月8日，替换开篇词、01讲～30讲；</li><li>1月29日，替换31讲～56讲，以及加餐和结束语。</li></ul><p>如果你还没有学完，或者是刚刚加入，那就跟着这个节奏，重新来学一遍吧。</p><p>希望这次全新迭代的音频，能带给你不一样的学习体验。也欢迎你继续提出问题、分享经验，我们一起学习、一起进步。</p><p>2021年刚刚开始，世界依然充满了种种不确定性，但是日日学习、点滴精进，这些都是确定的，而能给自己这种确定感的也只有我们自己。还等什么，就今天，就此刻，就从搞定一个算法、一个数据结构开始吧！ 精选留言（11） zqnba 👍（16） 💬（1）只是替换音频？内容有变化吗？2021-01-08Monday 👍（20） 💬（4）哟西，精益求精，就需要这样的态度2021-01-08Dylan 👍（8） 💬（1）算是最早一批订阅者，没想到已经十万的订阅量，期待极客时间后续更好的课程2021-01-08InHero 👍（3） 💬（0）感谢老师，用了一个半月学完了这个课程，但是感觉还要再刷一编，很多地方看完会忘，之后要开始刷题了2021-07-06Richie 👍（3） 💬（0）精益求精，赞2021-01-08梦想的优惠券 👍（2） 💬（1）那就再来亿遍2021-01-09Jie 👍（2） 💬（0）棒棒哒，再刷亿遍2021-01-08枫林残梦 👍（2） 💬（0）看了这么久还没看完，这次跟着一定得走一遍2021-01-08猫大叔 👍（1） 💬（0）太好了， 刚刚回去看了一下发现是冯永吉播的， 绝对赞！！！2021-01-21Seven 👍（1） 💬（0）那就来个三刷把2021-01-11罗耀龙@坐忘 👍（0） 💬（0）茶艺师学编程</p><p>好老师与好的团队！2021-03-01</p>",10)])])}const m=_(p,[["render",n]]);export{u as __pageData,m as default};
